cards.solution:
import java.time.*;

public class Main {
    public static void main(String[] args) {
        String teks = "2028-02-10";
        LocalDate d = LocalDate.parse(teks);
        System.out.println(d.lengthOfMonth());
        System.out.println(d.isLeapYear());
        System.out.println(d.getDayOfWeek());
    }
}

